  "fields": {
    "unit": {
      "value": "patient_regimen",
      "evidence": [
        "article:p27",
        "supp/Sheet1/A3"
      ],
      "explanation": "The study compares drug sensitivity of organoids to clinical response for specific patient-regimen pairs (e.g., LC96 treated with PC). The unit is the patient-drug combination."
    },
    "platform": {
      "value": "microwell",
      "evidence": [
        "article:p14",
        "article:p1"
      ],
      "explanation": "The study uses an 'integrated superhydrophobic microwell array chip (InSMAR-chip)'."
    },
    "readout": {
      "value": "viability",
      "evidence": [
        "article:p16",
        "article:p49"
      ],
      "explanation": "Cell viability is measured using alamarBlue (AB) assay, calculated as relative viability after drug treatment compared to control."
    },
    "direction": {
      "value": "lower_sensitive",
      "evidence": [
        "article:p20",
        "article:p25"
      ],
      "explanation": "Lower viability or lower AUC indicates higher sensitivity (e.g., EGFR-M group had significantly different/lower AUC/viability than WT)."
    },
    "threshold_rule": {
      "value": "categorical",
      "evidence": [
        "article:p27",
        "supp/Sheet1/I3"
      ],
      "explanation": "The authors report 100% accuracy and specificity based on a binary classification of clinical response (PD vs PR/CR/SD) matching organoid sensitivity (Resistant vs Sensitive). The specific numeric cutoff for 'sensitive' in vitro is not explicitly defined as a single universal threshold but implied by the agreement with clinical outcome categories."
    },
    "threshold_timing": {
      "value": "not_reported",
      "evidence": [
        "article:p27"
      ],
      "explanation": "The paper states 100% accuracy/specificity but does not report the specific numeric viability threshold used to binarize the organoid response for this calculation, nor does it state if it was prespecified."
    },
    "patient_mapping": {
      "value": "individual_available",
      "evidence": [
        "supp/Sheet1/A3",
        "supp/Sheet1/M3"
      ],
      "explanation": "Supplementary Data 2 links individual patient IDs (e.g., LC96) to specific agents tested and clinical responses."
    },
    "regimen_match": {
      "value": "matched",
      "evidence": [
        "article:p25",
        "supp/Sheet1/F3"
      ],
      "explanation": "The drugs tested on organoids (e.g., GC for LC134) match the systemic treatments received by the patients."
    },
    "n_units": {
      "value": 10,
      "evidence": [
        "article:p27"
      ],
      "explanation": "Article p27 states: 'In ten of the organoid lines... the 1-week drug sensitivity results were in great agreement with the clinical data'."
    },
    "split": {
      "value": "same_cohort",
      "evidence": [
        "article:p20",
        "article:p27"
      ],
      "explanation": "The clinical comparison is performed on the same set of patients from whom the organoids were derived, without an independent validation cohort mentioned for the accuracy metric."
    }
  },
